callGraph.callee:
func() {
		defer qrCancel()
		defer func() {
			c.qrFlowMu.Lock()
			c.qrFlowActive = false
			c.qrFlowMu.Unlock()
		}()
		for evt := range qrChan {
			if evt.Event == "code" {
				c.qrMutex.Lock()
				c.qrCode = evt.Code
				if pngBytes, err := qrcode.Encode(evt.Code, qrcode.Medium, 256); err == nil {
					c.qrBase64 = "data:image/png;base64," + base64.StdEncoding.EncodeToString(pngBytes)
				}
				c.qrMutex.Unlock()

				if c.onStatus != nil {
					c.onStatus(c.SessionID, "needs_rescan", c.qrBase64, "", "")
				}
			} else if evt.Event == "timeout" {
				logger.WithComponent("WhatsAppDriver").WithField("session_id", c.SessionID).Info("QR code expired")
				c.qrMutex.Lock()
				c.qrCode = ""
				c.qrBase64 = ""
				c.qrMutex.Unlock()
				if c.onStatus != nil {
					c.onStatus(c.SessionID, "needs_rescan", "", "", "")
				}
			} else {
				logger.WithComponent("WhatsAppDriver").WithFields(map[string]any{"session_id": c.SessionID, "event": evt.Event}).Debug("QR event received")
			}
		}
	}
